//! Fixed real Server navigation evidence; no renderer admission or live Rust claim.
use super::{application_protocol as app, world_protocol as world, native_player_loadout_evidence_tests as loadout};
use anyhow::{Result,ensure,Context};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn pointer()->Value{read(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r437-navigation-snapshot.json"))}
fn sha(b:&[u8])->String{Sha256::digest(b).iter().map(|x|format!("{x:02x}")).collect()}
fn unhex(s:&str)->Result<Vec<u8>>{ensure!(s.len()%2==0 && s.len()<=4*1024*1024,"hex bound");(0..s.len()).step_by(2).map(|i|Ok(u8::from_str_radix(&s[i..i+2],16)?)).collect()}
fn pinned(root:&Path,rel:&str)->Result<Vec<u8>>{let m=read(root.join("manifest.json"));let e=m["files"].as_array().context("manifest")?.iter().find(|e|e["path"]==rel).context("missing pin")?;let b=fs::read(root.join(rel))?;ensure!(b.len() as u64==e["bytes"].as_u64().context("bytes")?&&sha(&b)==e["sha256"].as_str().context("sha")?.to_ascii_lowercase(),"input drift");Ok(b)}
fn header(b:&[u8])->Result<(u32,u16)>{ensure!((16..=1024*1024).contains(&b.len())&&&b[..4]==b"LTM1","header bounds/magic");ensure!(u32::from_be_bytes(b[4..8].try_into()?) as usize==b.len()&&b[14..16]==[0,0],"length/reserved");let id=u32::from_be_bytes(b[8..12].try_into()?);ensure!(id!=0,"request id");Ok((id,u16::from_be_bytes(b[12..14].try_into()?)))}
fn complete(q:&[u8],r:&[u8])->Result<Option<app::ResponseFrame>>{let (id,k)=header(q)?;let (rid,rk)=header(r)?;ensure!(id==rid,"response request id");if k==1{ensure!(q.len()==32&&r.len()==24&&rk==2&&q[16..]==[0,26,0,26,0,1,0,255,0,1,0,255,0,1,0,0]&&r[16..]==[0,26,0,1,0,1,0,255],"handshake");return Ok(None);}
 let response=app::decode_response_version(r,26)?;
 match &response.response{
  app::Response::Characters{source_id,epoch,..}=>ensure!(q.len()==28&&q[16..20]==source_id.to_be_bytes()&&q[20..28]==epoch.to_be_bytes(),"roster scope"),
  app::Response::Navigation(v)=>{let c=v.context;ensure!(q.len()>=36&&q[16..20]==c.key.source_id.to_be_bytes()&&q[20..28]==c.key.object_id.to_be_bytes()&&q[28..36]==c.epoch.to_be_bytes(),"navigation selected owner scope");},
  app::Response::Rooms(v)=>{let c=v.common.context;ensure!(q.len()>=56&&q[16..20]==c.key.source_id.to_be_bytes()&&q[20..28]==c.key.object_id.to_be_bytes()&&q[28..36]==c.epoch.to_be_bytes()&&q[36..56]==r[36..56],"room complete common echo");},
  app::Response::World(reply)=>ensure!(world::encode_request(id,&reply.echo)?==q,"full world request echo"),
  app::Response::Equipment(reply)=>{let c=reply.request.context;ensure!(q.len()==88&&rk==17&&q[16..20]==c.key.source_id.to_be_bytes()&&q[20..28]==c.key.object_id.to_be_bytes()&&q[28..36]==c.epoch.to_be_bytes(),"gear owner");ensure!(q[36..40]==[match reply.request.action{super::equipment::Action::Read=>0,super::equipment::Action::Set=>1},u8::from(reply.request.desired),0,0]&&q[40..48]==reply.request.item_id.to_be_bytes()&&q[48..56]==reply.request.expected_revision.to_be_bytes()&&q[56..88]==reply.request.expected_view_token,"gear complete echo");},
  app::Response::Combat(reply)=>ensure!(super::combat_protocol::encode_request(id,&reply.echo)?==q,"combat complete echo"),
  _=>{}
 }Ok(Some(response))}
fn families()->Vec<(&'static str,PathBuf,&'static str)>{let p=pointer();vec![("candidate",PathBuf::from(p["candidate"]["root"].as_str().unwrap()),"evidence/"),("replay",PathBuf::from(p["replay"]["root"].as_str().unwrap()),"")]}
#[test]fn fixed_complete_navigation_bodies_and_exact_work_projections(){let mut all=Vec::new();let mut projections=Vec::new();for (family,root,prefix) in families(){let capture:Value=serde_json::from_slice(&pinned(&root,&format!("{prefix}navigation-tls-capture.json")).unwrap()).unwrap();let vectors:Value=serde_json::from_slice(&pinned(&root,&format!("{prefix}navigation-tls-vectors.json")).unwrap()).unwrap();let mut total=0;let mut count=0;let mut eof=Vec::new();let mut sessions=BTreeSet::new();let mut requests=BTreeSet::new();let mut phases=BTreeSet::new();let mut rows=Vec::new();let mut gear=Vec::new();
 for (i,e) in capture["entries"].as_array().unwrap().iter().enumerate(){assert_eq!(e["sequence"],i+1);let q=unhex(e["request_hex"].as_str().unwrap()).unwrap();let (id,k)=header(&q).unwrap();let session=e["session"].as_u64().unwrap();assert!(requests.insert((session,id)));sessions.insert(session);assert_eq!(e["request_id"],id);assert_eq!(e["request_kind"],k);assert_eq!(vectors[format!("{}_request{k}_hex",e["key"].as_str().unwrap())],e["request_hex"]);total+=q.len();if e["outcome"]=="EOF_REJECTED"{assert!(e.get("response_hex").is_none());eof.push(e["action"].clone());continue;}
 assert_eq!(e["outcome"],"COMPLETE_EXCHANGE");let r=unhex(e["response_hex"].as_str().unwrap()).unwrap();let (_,rk)=header(&r).unwrap();assert_eq!(e["response_kind"],rk);assert_eq!(vectors[format!("{}_result{rk}_hex",e["key"].as_str().unwrap())],e["response_hex"]);let decoded=complete(&q,&r).unwrap_or_else(|error|panic!("{family} sequence {}: {error}",i+1));total+=r.len();count+=1;
 if let Some(d)=decoded{match &d.response{app::Response::World(v)=>{if let Some(f)=&v.frame{phases.insert(format!("{:?}",f.phase));let desc=f.descriptor.as_ref().unwrap();assert_eq!(desc.features,world::MatchDescriptor::COMBAT);assert_eq!(desc.ruleset,world::MatchRuleset::PvpSkirmish);assert_eq!(f.actors.len(),2);assert_eq!(f.manifest.map_id,564);assert!(f.completion.is_none());}},app::Response::Equipment(v)=>{let s=v.snapshot.as_ref().unwrap();assert_eq!(s.source.items.len(),29);gear.push(json!({"sequence":i+1,"source":s.source.context.key.source_id,"revision":s.revision,"AC":s.source.stats.armor_class,"changed":v.changed,"flags":s.flags.iter().map(|f|json!({"id":f.item_id,"equipped":f.equipped})).collect::<Vec<_>>() }));},app::Response::Combat(v)=>{let f=v.frame.as_ref().unwrap();assert_eq!(f.vitals.len(),2);assert!(f.vitals.iter().all(|v|v.weapon_type==3&&v.max_hp==544));},_=>{}}rows.push(json!({"sequence":i+1,"kind":rk,"decoded_complete_body":format!("{:?}",d.response)}));}}
 assert_eq!(count,53);assert_eq!(sessions.len(),4);assert_eq!(total as u64,capture["wire_bytes"].as_u64().unwrap());assert_eq!(eof,vec![json!("wrong_source"),json!("stale_epoch")]);assert!(phases.contains("Loading")&&phases.contains("Active"));assert_eq!(gear.len(),8);
 let mut cases=BTreeMap::new();for name in ["source7-initial","source42-initial","source7-after-CAS","source42-after-other-CAS","source7-after-real-armor-CAS","source42-after-other-armor-CAS","source7-actual-SQL-timed-fixture","source7-reselected-actual-character"]{let b=pinned(&root,&format!("{prefix}{name}.lpl")).unwrap();let jb=pinned(&root,&format!("{prefix}{name}.json")).unwrap();let j:Value=serde_json::from_slice(&jb).unwrap();let mut owner=loadout::expected(name);if name.contains("timed"){owner.epoch=i64::MIN+2;}let v=loadout::verify(&b,&j,owner).unwrap_or_else(|error|panic!("{family} {name}: {error}"));
 if let Some(sequence)=match name{"source7-initial"=>Some(9),"source7-after-CAS"=>Some(11),"source7-after-real-armor-CAS"=>Some(13),"source7-actual-SQL-timed-fixture"=>Some(16),_=>None}{let g=gear.iter().find(|g|g["sequence"]==sequence).unwrap();assert_eq!(g["revision"],j["equipment_revision"]);let flags:Vec<_>=g["flags"].as_array().unwrap().iter().map(|f|json!({"objectId":f["id"],"equipped":f["equipped"]})).collect();assert_eq!(json!(flags),j["equipped"]);}
 cases.insert(name.to_owned(),j);projections.push(json!({"family":family,"case":name,"projection_sha256":sha(&b),"exact_work_bundle_sha256":sha(&jb),"details":v}));}
 for name in ["source42-after-other-CAS","source42-after-other-armor-CAS"]{for key in ["effective","equipped","equipment_revision"]{assert_eq!(cases[name][key],cases["source42-initial"][key]);}}assert_eq!(cases["source7-after-CAS"]["weapon_state"],"UNARMED");assert_eq!(cases["source7-after-real-armor-CAS"]["effective"]["armorClass"],-3);assert_eq!(cases["source7-after-real-armor-CAS"]["modifiers"]["MR"],4);
 all.push(json!({"family":family,"records":55,"complete_exchanges":count,"wire_bytes":total,"EOF":eof,"full_gear":gear,"complete_bodies":rows}));}
 fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r437-navigation-consumer-details.json"),serde_json::to_vec_pretty(&json!({"state":"RUST_FULL_NAVIGATION_AND_EXACT_WORK_LPL1_OFFLINE_VERIFIED","families":all,"projections":projections,"Rust_live_SQL_TLS":false,"renderer_LOADED":false,"GUI":0,"projection_is_session_authority":false})).unwrap()).unwrap();}
#[test]fn complete_body_truncation_trailing_and_owner_corruption_reject(){let (_,root,prefix)=families().remove(1);let c:Value=serde_json::from_slice(&pinned(&root,&format!("{prefix}navigation-tls-capture.json")).unwrap()).unwrap();let mut kinds=BTreeSet::new();for e in c["entries"].as_array().unwrap(){if e["outcome"]!="COMPLETE_EXCHANGE"{continue;}let q=unhex(e["request_hex"].as_str().unwrap()).unwrap();let r=unhex(e["response_hex"].as_str().unwrap()).unwrap();let (_,k)=header(&r).unwrap();if ![17,19,21,23].contains(&k)||!kinds.insert(k){continue;}for cut in [16, r.len()-1]{let mut bad=r[..cut].to_vec();bad[4..8].copy_from_slice(&(cut as u32).to_be_bytes());assert!(complete(&q,&bad).is_err());}let mut bad=r.clone();bad.push(0);let n=bad.len() as u32;bad[4..8].copy_from_slice(&n.to_be_bytes());assert!(complete(&q,&bad).is_err());let mut bad=r.clone();bad[14]=1;assert!(complete(&q,&bad).is_err());if [17,21,23].contains(&k){let mut bad=r;bad[19]^=1;assert!(complete(&q,&bad).is_err());}}assert_eq!(kinds.len(),4);}
#[test]fn actual_work_lifecycle_and_expiry_guard_evidence_are_bound(){for (_,root,prefix) in families(){let probe:Value=serde_json::from_slice(&pinned(&root,&format!("{prefix}navigation-work-probe.json")).unwrap()).unwrap();assert_eq!(probe["state"],"PASSED_ACTUAL_SELECTED_OWNER_NAVIGATION_SQL_TLS");for key in ["actual_TLS_world_prepare_to_SQL_and_melee_publication","BACK_reselection_disconnect_and_actual_deadline_rejected","all_retired_readers_rejected_before_SQL","expiry_between_SQL_read_and_publication_real_wall_clock","TLS_cross_source_and_stale_epoch_EOF","TLS_listener_released","server_retired"]{assert_eq!(probe[key],true);}assert_eq!(probe["test_selection_issuer"],false);assert_eq!(probe["provider_calls"],14);let d=&probe["actual_SQL_deadline_observation"];let cutoff=d["cutoff_exclusive"].as_i64().unwrap();assert_eq!(d["provider_finished_at_millis"].as_i64().unwrap(),cutoff+1);assert!(d["backend_remaining_nanos"].as_i64().unwrap()>500_000_000);assert_eq!(d["item"],10304);
 let reads:Value=serde_json::from_slice(&pinned(&root,&format!("{prefix}navigation-provider-reads.json")).unwrap()).unwrap();assert_eq!(reads.as_array().unwrap().len(),14);assert!(reads.as_array().unwrap().iter().all(|r|r["backend_scope_bound"]==true&&r["canonical_account"]=="3333"));assert_eq!(reads[9]["object"],10163);let report:Value=serde_json::from_slice(&pinned(&root,&format!("{prefix}navigation-sql-probe.json")).unwrap()).unwrap();assert_eq!(report["dynamic_before"],report["dynamic_after"]);assert_eq!(report["dynamic_after"].as_object().unwrap().len(),172);assert_eq!(report["active_SQL_connections_before_shutdown"],0);assert_eq!(report["mysql_process_retired"],true);assert_eq!(report["mysql_listener_released"],true);}
 let p=pointer();let root=Path::new(p["candidate"]["root"].as_str().unwrap());let diff=String::from_utf8(pinned(root,"provenance/three-source-changes.diff").unwrap()).unwrap();for guard in ["atRead.desiredLoadout().items()","now>=view.expiresAtMillis()","loadout source lifetime elapsed after SQL observation","attachment.lease.operation(backendScope)","!captured.currentAt(System.currentTimeMillis())","absoluteDeadlineNanos >= 0"]{assert!(diff.contains(guard),"missing source guard {guard}");}}
